<?php
require __DIR__.'/app/bootstrap.php';maintenance_gate();$page=max(1,(int)($_GET['page']??1));
$st=db()->prepare('SELECT t.*,c.title category_title,c.slug category_slug FROM topics t JOIN categories c ON c.id=t.category_id WHERE t.is_hidden=0 AND c.is_visible=1 ORDER BY t.is_pinned DESC,t.last_activity_at DESC,t.id DESC LIMIT 31 OFFSET ?');$st->bindValue(1,($page-1)*30,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$more=count($rows)>30;
forum_header('Усі теми');?><section class="page-title"><a href="/">← Форум</a><h1>Усі теми</h1></section><div class="search-results"><?php foreach(array_slice($rows,0,30) as $t):?><a class="panel" href="/topic.php?slug=<?=urlencode($t['slug'])?>"><h2><?=e($t['title'])?></h2><small><?=e($t['category_title'])?> · <?=e(format_forum_date($t['last_activity_at']))?> <?=$t['is_pinned']?'· закріплено':''?></small></a><?php endforeach;?></div><nav class="pagination"><?php if($page>1):?><a href="?page=<?=$page-1?>">← Попередня</a><?php endif;?><?php if($more):?><a href="?page=<?=$page+1?>">Наступна →</a><?php endif;?></nav><?php forum_footer();
